using UnityEngine;
namespace Vanta.Vehicles{public sealed class VehicleInteraction:MonoBehaviour{[SerializeField]float enterRange=3f;[SerializeField]Transform seat;public bool IsOccupied{get;private set;}public bool TryEnter(Transform player){if(IsOccupied||player==null||Vector3.Distance(transform.position,player.position)>enterRange)return false;IsOccupied=true;player.SetParent(seat?seat:transform);player.localPosition=Vector3.zero;player.localRotation=Quaternion.identity;return true;}public void Exit(Transform player){if(!IsOccupied||player==null)return;player.SetParent(null);player.position=transform.position+transform.right*2f;IsOccupied=false;}}}